INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '構成比の計算', '下の表は、ある家庭の1か月の支出内訳を表したものである。支出全体に占める「食費」の割合は何%か（小数第1位まで）。', '[{"headers":["項目","金額（万円）"],"rows":[["食費","9.6"],["住居費","14.4"],["光熱費","3.6"],["通信費","2.4"],["その他","6.0"]]}]', '["26.7%","30.0%","24.0%","20.0%"]', 0, '["支出合計＝9.6＋14.4＋3.6＋2.4＋6.0＝36.0万円","食費の割合＝9.6÷36.0≈26.7%","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '構成比の計算', '下の表は、ある会社の従業員数を年代別に表したものである。全従業員に占める「40代」の割合は何%か（小数第1位まで）。', '[{"headers":["年代","人数（人）"],"rows":[["20代","45"],["30代","68"],["40代","82"],["50代","39"],["60代以上","16"]]}]', '["32.8%","30.0%","34.0%","28.0%"]', 0, '["従業員数の合計＝45＋68＋82＋39＋16＝250人","40代の割合＝82÷250＝32.8%","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '構成比の計算', '下の表は、ある自治体の年間予算の内訳を表したものである。予算全体に占める「人件費」と「設備費」の合計の割合は何%か。', '[{"headers":["項目","金額（億円）"],"rows":[["人件費","18"],["設備費","12"],["広告費","6"],["研究費","9"],["その他","5"]]}]', '["60.0%","54.0%","66.0%","50.0%"]', 0, '["予算合計＝18＋12＋6＋9＋5＝50億円","人件費と設備費の合計＝18＋12＝30億円","割合＝30÷50＝60.0%","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '倍率の計算', '下の表は、A社とB社の年間売上を表したものである。A社の売上は、B社の売上の何倍か。', '[{"headers":["会社","売上（百万円）"],"rows":[["A社","912"],["B社","228"]]}]', '["4.0倍","3.5倍","4.5倍","3.0倍"]', 0, '["倍率＝比較する数（A社）÷基準にする数（B社）＝912÷228＝4.0倍","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '倍率の計算', '下の表は、あるイベントの来場者数の推移を表したものである。2024年の来場者数は、2022年の何倍か。', '[{"headers":["年","来場者数（人）"],"rows":[["2022","1,850"],["2023","2,960"],["2024","5,550"]]}]', '["3.0倍","2.5倍","3.5倍","2.0倍"]', 0, '["倍率＝5,550÷1,850＝3.0倍","コツ：間の年（2023年）の数値は今回の計算には使いません。惑わされないようにしましょう。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '増加率の計算', '下の表は、ある会社の売上を表したものである。2024年から2025年にかけて、売上は何%伸びたか。', '[{"headers":["年","売上（百万円）"],"rows":[["2024","680"],["2025","782"]]}]', '["15.0%","12.0%","18.0%","10.0%"]', 0, '["増加率＝（新しい数値－古い数値）÷古い数値＝（782－680）÷680＝102÷680＝15.0%","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '増加率の計算', '下の表は、4つのサービスの利用者数を表したものである。前年比の増加率が最も高いサービスはどれか。', '[{"headers":["サービス","前年","今年"],"rows":[["P","42,000","48,300"],["Q","65,000","71,500"],["R","38,000","44,460"],["S","54,000","58,320"]]}]', '["P","Q","R","S"]', 2, '["P：(48,300－42,000)÷42,000＝15.0%／Q：(71,500－65,000)÷65,000＝10.0%／R：(44,460－38,000)÷38,000＝17.0%／S：(58,320－54,000)÷54,000＝8.0%","最も高いのはRです。","よって、正解は3（R）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '減少率の計算', '下の表は、4つの項目の前年と今年の数値を表したものである。前年比で最も減少率が大きい項目はどれか。', '[{"headers":["項目","前年","今年"],"rows":[["A","9,500","8,075"],["B","7,200","6,192"],["C","12,800","11,264"],["D","6,400","5,952"]]}]', '["A","B","C","D"]', 0, '["A：(9,500－8,075)÷9,500＝15.0%／B：(7,200－6,192)÷7,200＝14.0%／C：(12,800－11,264)÷12,800＝12.0%／D：(6,400－5,952)÷6,400＝7.0%","最も大きいのはAです。","よって、正解は1（A）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '減少率の計算', '下の表は、4つの項目の前年と今年の数値を表したものである。前年比で最も減少率が大きい項目はどれか。', '[{"headers":["項目","前年","今年"],"rows":[["X","20,000","18,000"],["Y","8,000","6,000"],["Z","15,000","13,650"],["W","5,000","4,500"]]}]', '["X","Y","Z","W"]', 1, '["X：(20,000－18,000)÷20,000＝10.0%／Y：(8,000－6,000)÷8,000＝25.0%／Z：(15,000－13,650)÷15,000＝9.0%／W：(5,000－4,500)÷5,000＝10.0%","コツ：XとYは減少した実数（2,000）が同じですが、分母（前年の数値）が小さいYの方が減少率は大きくなります。実数の大小に惑わされないようにしましょう。","最も大きいのはYです。","よって、正解は2（Y）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '減少率の計算', '下の表は、ある会社の売上を表したものである。2022年から2024年までの2年間で、売上は何%増加したか。', '[{"headers":["年","売上（百万円）"],"rows":[["2022","400"],["2023","460"],["2024","540"]]}]', '["35.0%","27.5%","20.0%","40.0%"]', 0, '["増加率＝（540－400）÷400＝140÷400＝35.0%","コツ：2023年の数値は途中経過であり、2022年から2024年への変化率の計算には使いません。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '人口密度・平均の計算', '下の表は、ある工場の従業員数と生産量を表したものである。従業員1人あたりの生産量は何個か。', '[{"headers":["項目","数値"],"rows":[["従業員数","80人"],["生産量","14,400個"]]}]', '["180個","160個","200個","150個"]', 0, '["1人あたりの生産量＝合計÷単位（人数）＝14,400÷80＝180個","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '人口密度・平均の計算', '下の表は、ある町の面積と人口を表したものである。この町の人口密度は何人/km²か。', '[{"headers":["項目","数値"],"rows":[["面積","62km²"],["人口","38,440人"]]}]', '["620人/km²","600人/km²","650人/km²","580人/km²"]', 0, '["人口密度＝人口÷面積＝38,440÷62＝620人/km²","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '単位の引っ掛け', '下の表は、ある会社の年間売上を表したものである（単位：千円）。この売上を「億円」単位で表すと何億円か。', '[{"headers":["年","売上（千円）"],"rows":[["2024","456,000"]]}]', '["4.56億円","45.6億円","0.456億円","456億円"]', 0, '["456,000千円＝456,000,000円です。1億円＝100,000,000円なので、","456,000,000÷100,000,000＝4.56億円","コツ：「千円」→「円」でゼロを3つ足し、さらに「円」→「億円」でゼロを8つ減らす（＝10^8で割る）と考えると、ゼロの数を数え間違えにくくなります。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '単位の引っ掛け', '下の表は、ある都市の人口を表したものである（単位：百人）。この人口を「万人」単位で表すと何万人か。', '[{"headers":["都市","人口（百人）"],"rows":[["A市","1,285"]]}]', '["12.85万人","1.285万人","128.5万人","0.1285万人"]', 0, '["1,285百人＝128,500人です。1万人＝10,000人なので、","128,500÷10,000＝12.85万人","コツ：「百人」→「人」でゼロを2つ足し、「人」→「万人」でゼロを4つ減らす、と整理するとミスを防げます。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '単位の引っ掛け', '下の表は、ある県の面積と生産額を表したものである（生産額の単位：百万円）。面積1km²あたりの生産額は何百万円か。', '[{"headers":["項目","数値"],"rows":[["面積","450km²"],["生産額","27,000百万円"]]}]', '["60百万円/km²","50百万円/km²","65百万円/km²","55百万円/km²"]', 0, '["1km²あたりの生産額＝27,000÷450＝60百万円/km²","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '最大・最小の特定', '下の表は、5つの都市の人口と財政支出総額を表したものである。住民1人あたりの財政支出が最も多いのはどこか。', '[{"headers":["都市","人口（人）","財政支出総額（百万円）"],"rows":[["あ市","120,000","18,000"],["い市","45,000","9,900"],["う市","300,000","42,000"],["え市","18,000","1,800"],["お市","65,000","16,900"]]}]', '["あ市","い市","う市","え市","お市"]', 4, '["コツ：まず全部を計算せず、明らかに見劣りする候補を除外します。う市は人口が飛び抜けて多い（30万人）わりに財政支出総額はさほど大きくないため、1人あたりでは低くなりやすいと予想できます。え市も総額が小さく、有力候補ではなさそうです。残るあ・い・おを計算します。","あ：18,000百万円÷120,000人＝150,000円／い：9,900百万円÷45,000人＝220,000円／お：16,900百万円÷65,000人＝260,000円","（参考：う＝42,000÷300,000＝140,000円、え＝1,800÷18,000＝100,000円で、予想通り低い結果でした）","最も多いのはお市です。","よって、正解は5（お市）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '最大・最小の特定', '下の表は、5社の売上と利益を表したものである。利益率（利益÷売上）が最も高い会社はどれか。', '[{"headers":["会社","売上（億円）","利益（億円）"],"rows":[["A社","120","6"],["B社","8","1.2"],["C社","340","44.2"],["D社","55","9.35"],["E社","200","18"]]}]', '["A社","B社","C社","D社","E社"]', 3, '["コツ：A社は売上に対して利益が非常に小さく（120に対して6）、比率は明らかに低いと予想できるので早めに除外できます。","A：6÷120＝5.0%／B：1.2÷8＝15.0%／C：44.2÷340＝13.0%／D：9.35÷55＝17.0%／E：18÷200＝9.0%","最も高いのはD社です。","よって、正解は4（D社）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '最大・最小の特定', '下の表は、5つの商品の販売数と総利益を表したものである。1個あたりの利益（総利益÷販売数）が2番目に高い商品はどれか。', '[{"headers":["商品","販売数（個）","総利益（円）"],"rows":[["P","1,200","180,000"],["Q","800","152,000"],["R","1,500","232,500"],["S","950","171,000"],["T","2,100","294,000"]]}]', '["P","Q","R","S","T"]', 3, '["P：180,000÷1,200＝150円／Q：152,000÷800＝190円／R：232,500÷1,500＝155円／S：171,000÷950＝180円／T：294,000÷2,100＝140円","高い順に、Q(190円)＞S(180円)＞R(155円)＞P(150円)＞T(140円)となります。","2番目に高いのはSです。","よって、正解は4（S）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '最大・最小の特定', '下の表は、4支店の売り場面積と売上を表したものである。面積1㎡あたりの売上が最も低い支店はどこか。', '[{"headers":["支店","面積（㎡）","売上（万円）"],"rows":[["甲","450","13,500"],["乙","120","4,800"],["丙","800","16,000"],["丁","60","3,000"]]}]', '["甲","乙","丙","丁"]', 2, '["コツ：丙は面積が他店より飛び抜けて大きい（800㎡）ため、面積あたりの売上では最も低くなりやすい候補として真っ先にチェックすべきです。","甲：13,500÷450＝30万円／乙：4,800÷120＝40万円／丙：16,000÷800＝20万円／丁：3,000÷60＝50万円","最も低いのは丙です。","よって、正解は3（丙）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '最大・最小の特定', '下の表は、5つの地域の面積と予算総額を表したものである。面積1km²あたりの予算額が2番目に大きい地域はどれか。', '[{"headers":["地域","面積（km²）","予算（百万円）"],"rows":[["a","180","5,400"],["b","45","2,250"],["c","320","6,400"],["d","90","4,050"],["e","60","3,600"]]}]', '["a","b","c","d","e"]', 1, '["コツ：cは面積が最も大きい（320km²）のに予算はそれほど突出していないため、1km²あたりでは低くなりやすいと予想でき、優先度を下げられます。","a：5,400÷180＝30百万円／b：2,250÷45＝50百万円／c：6,400÷320＝20百万円／d：4,050÷90＝45百万円／e：3,600÷60＝60百万円","高い順に、e(60)＞b(50)＞d(45)＞a(30)＞c(20)となります。","2番目に大きいのはbです。","よって、正解は2（b）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
